class Account {
public:
    explicit Account(int balance) : balance_(balance) {}

    bool withdraw(int amount) {
        if (amount > balance_) return false;
        balance_ -= amount;
        return true;
    }
    int balance() const { return balance_; }

private:
    int balance_;
};

Account acc(1000);
acc.withdraw(300);
std::cout << acc.balance() << '\n';
std::cout << acc.withdraw(5000) << '\n';

#include <memory>

