};

int main() {
    {
        auto r = std::make_unique<Res>();
        std::cout << "使用中\n";
    }   // ここで自動的に解放される
    std::cout << "スコープ外\n";
}

template <typename T>
T maxOf(T a, T b) {
    return (a > b) ? a : b;
}

template <typename T>
class Box {
public:
    explicit Box(T v) : v_(v) {}
    T get() const { return v_; }
private:
    T v_;
};

std::cout << maxOf(3, 9) << ' ' << maxOf(2.5, 1.5) << '\n';
Box<int> bi(7);
Box<std::string> bs("hi");
std::cout << bi.get() << ' ' << bs.get() << '\n';
